const body = $json.body || $json;
const reference = body.reference_text || body.referenceText || body.prompt || 'Brand campaign';
const count = Math.max(1, Number(body.output_count || body.outputCount || 2));
const options = Array.from({ length: count }, (_, index) => ({
  title: `Option ${index + 1}`,
  description: `${reference} - creative direction ${index + 1}`,
  prompt: `${reference}. Produce a polished social media concept with clear subject, lighting, composition, and campaign CTA. Variant ${index + 1}.`,
  variant: String(index + 1).padStart(2, '0')
}));
return [{ json: { job_id: body.job_id || null, options } }];

const body = $json.body || $json;
const prompt = body.prompt || body.description || body.post_text || 'AI generated campaign image';
const count = Math.max(1, Number(body.output_count || body.outputCount || 2));
const ratio = body.aspect_ratio || body.aspectRatio || '1:1';
const sizeByRatio = {
  '16:9': '1280/720',
  '9:16': '720/1280',
  '1:1': '1200/1200'
};
const size = sizeByRatio[ratio] || sizeByRatio['1:1'];
const seedText = `${body.job_id || ''}:${prompt}`;
let hash = 0;
for (let index = 0; index < seedText.length; index += 1) {
  hash = ((hash << 5) - hash + seedText.charCodeAt(index)) >>> 0;
}
const image_urls = Array.from({ length: count }, (_, index) => `https://picsum.photos/seed/${hash}-${index + 1}/${size}`);
return [{
  json: {
    job_id: body.job_id || null,
    status: 'ready',
    provider: 'demo-image-generator',
    prompt,
    aspect_ratio: ratio,
    image_urls,
    urls: image_urls,
    generated_at: new Date().toISOString()
  }
}];

const body = $json.body || $json;
const prompt = body.prompt || body.description || body.topic || 'AI generated campaign video';
const count = Math.max(1, Number(body.output_count || body.outputCount || 2));
const demoVideos = [
  'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4',
  'https://media.w3.org/2010/05/sintel/trailer.mp4'
];
const video_urls = Array.from({ length: count }, (_, index) => demoVideos[index % demoVideos.length]);
return [{
  json: {
    job_id: body.job_id || null,
    status: 'ready',
    provider: 'demo-video-generator',
    prompt,
    reference_text: body.reference_text || body.referenceText || '',
    aspect_ratio: body.aspect_ratio || body.aspectRatio || '16:9',
    video_urls,
    urls: video_urls,
    generated_at: new Date().toISOString()
  }
}];

const body = $json.body || $json;
const parseJson = (value, fallback) => {
  if (Array.isArray(value) || (value && typeof value === 'object')) return value;
  if (typeof value !== 'string' || value.trim() === '') return fallback;
  try { return JSON.parse(value); } catch { return fallback; }
};
const platforms = parseJson(body.platforms, body.platforms ? [body.platforms] : []);
const schedulePlan = parseJson(body.schedule_plan || body.schedule_details, []);
const scheduleAt = body.scheduled_at || body.schedule_at || schedulePlan?.[0]?.scheduled_at || null;
return [{
  json: {
    job_id: body.job_id || null,
    status: scheduleAt ? 'scheduled' : 'ready_to_publish',
    provider: 'demo-publisher',
    media_url: body.media_url || body.mediaUrl || '',
    content_type: body.content_type || 'image',
    platforms,
    caption: body.caption || '',
    hashtags: body.hashtags || '',
    scheduled_at: scheduleAt,
    schedule_plan: schedulePlan,
    queued_at: new Date().toISOString(),
    message: scheduleAt ? `Queued for ${scheduleAt}` : 'No schedule time received; ready for manual publishing.'
  }
}];
